from __future__ import annotations

def slugify(text: str) -> str:
    """Convert text to a URL-safe slug.

    Examples
    --------
    >>> slugify("Hello, World!")
    'hello-world'
    """
    result_chars: list[str] = []
    for char in text:
        if char.isalnum() or char == '_':
            result_chars.append(char)
        elif char.isspace() or char == "-":
            # Avoid adding multiple dashes in a row
            if len(result_chars) > 1 and result_chars[-2] == "-":
                result_chars.pop()
            result_chars.append("-")  
    collapsed = "".join(result_chars)
    return collapsed.strip("-").replace("--", "-")

def truncate(text: str, max_len: int, suffix: str = "…") -> str:
    """Truncate text to at most max_len characters including the suffix.
    If text is already short enough, return it unchanged.
    """
    if len(text) <= max_len:
        return text
    return text[:max_len - len(suffix)] + suffix"}

